import React from 'react';
import {AbsoluteFill, Easing, interpolate} from 'remotion';
import {useS, en, clamp, DUR} from './kit';

const W = 1080;
const H = 1920;

const T_DESPERTASTE = en('despertaste');
const T_PESO = en('peso');
const T_GRACIAS = en('gracias');
const T_PRESENCIA = en('presencia');
const T_FATIGA = en('fatiga');
const T_ENTREGO = en('entrego');
const T_CALMA = en('calma');
const T_SERENIDAD = en('serenidad');
const T_SOLEDAD = en('soledad');
const T_FUERZAS = en('fuerzas');
const T_CAMBIAR = en('cambiar');
const T_CONMIGO = en('conmigo');
const T_AMEN = en('amén');

const mezclarRGB = (a: [number, number, number], b: [number, number, number], k: number): string => {
  const f = Math.max(0, Math.min(1, k));
  const r = Math.round(a[0] + (b[0] - a[0]) * f);
  const g = Math.round(a[1] + (b[1] - a[1]) * f);
  const bl = Math.round(a[2] + (b[2] - a[2]) * f);
  return `rgb(${r}, ${g}, ${bl})`;
};

const Cielo: React.FC<{aurora: number; dorada: number}> = ({aurora, dorada}) => {
  const c1 = mezclarRGB([15, 20, 48], [42, 60, 110], aurora);
  const c2 = mezclarRGB([28, 32, 64], [185, 120, 105], aurora);
  const cTop = mezclarRGB([42, 60, 110], [92, 142, 214], dorada);
  const cMid = mezclarRGB([185, 120, 105], [245, 178, 128], dorada);
  const cBot = mezclarRGB([40, 36, 68], [255, 226, 168], dorada);
  const topFinal = aurora < 1 ? c1 : cTop;
  const midFinal = aurora < 1 ? c2 : cMid;
  const botFinal = aurora < 1 ? mezclarRGB([24, 24, 52], [140, 80, 95], aurora) : cBot;
  return <AbsoluteFill style={{background: `linear-gradient(180deg, ${topFinal} 0%, ${midFinal} 55%, ${botFinal} 100%)`}} />;
};

const SolNaciente: React.FC<{salida: number; s: number}> = ({salida, s}) => {
  const y = interpolate(salida, [0, 1], [1380, 930], clamp);
  const respiracion = Math.sin(s * 1.5) * 8;
  const tam = 260 + respiracion;
  return (
    <div style={{position: 'absolute', left: W / 2 - tam, top: y - tam, width: tam * 2, height: tam * 2, opacity: salida}}>
      <div style={{position: 'absolute', inset: -180, borderRadius: '50%', background: 'radial-gradient(circle, rgba(255, 230, 170, 0.6) 0%, rgba(255, 195, 120, 0.25) 45%, transparent 75%)'}} />
      <div style={{position: 'absolute', inset: 0, borderRadius: '50%', background: 'radial-gradient(circle at 45% 40%, #ffffff 0%, #ffefc2 40%, #ffb35a 100%)', boxShadow: '0 0 140px 60px rgba(255, 215, 140, 0.75)'}} />
    </div>
  );
};

const HacesLuz: React.FC<{intensidad: number; s: number}> = ({intensidad, s}) => (
  <AbsoluteFill style={{opacity: intensidad * 0.45, mixBlendMode: 'screen'}}>
    {Array.from({length: 8}).map((_, i) => {
      const angulo = -36 + i * 10.5 + Math.sin(s * 0.4 + i) * 1.8;
      return <div key={i} style={{position: 'absolute', left: W / 2 - 50, top: 920, width: 100, height: 1800, transformOrigin: '50% 0%', transform: `rotate(${angulo}deg)`, background: 'linear-gradient(180deg, rgba(255, 245, 205, 0.75) 0%, rgba(255, 220, 160, 0.2) 60%, transparent 95%)', filter: 'blur(16px)'}} />;
    })}
  </AbsoluteFill>
);

const Colinas: React.FC<{aurora: number; dorada: number; deriva: number}> = ({aurora, dorada, deriva}) => {
  const colFondo1 = mezclarRGB([22, 28, 56], [70, 78, 120], aurora);
  const colFondo2 = mezclarRGB([14, 18, 42], [48, 52, 90], aurora);
  const colFrente1 = mezclarRGB([18, 22, 45], [115, 96, 122], dorada);
  const colFrente2 = mezclarRGB([10, 12, 28], [58, 46, 68], dorada);
  return (
    <>
      <svg width={W + 160} height={650} style={{position: 'absolute', left: -80 + deriva * 0.25, top: 920}} viewBox={`0 0 ${W + 160} 650`}>
        <linearGradient id="gLejos" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor={colFondo1} /><stop offset="100%" stopColor={colFondo2} /></linearGradient>
        <path d={`M0 240 C 260 120, 480 320, 720 180 S 1120 100, ${W + 160} 220 L ${W + 160} 650 L 0 650 Z`} fill="url(#gLejos)" />
      </svg>
      <svg width={W + 200} height={750} style={{position: 'absolute', left: -100 + deriva * 0.5, top: 1120}} viewBox={`0 0 ${W + 200} 750`}>
        <linearGradient id="gCerca" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor={colFrente1} /><stop offset="100%" stopColor={colFrente2} /></linearGradient>
        <path d={`M0 320 C 320 200, 600 420, 860 260 S 1180 180, ${W + 200} 340 L ${W + 200} 750 L 0 750 Z`} fill="url(#gCerca)" />
        <path d={`M0 320 C 320 200, 600 420, 860 260 S 1180 180, ${W + 200} 340`} fill="none" stroke="rgba(255, 235, 185, 0.45)" strokeWidth={4} opacity={dorada} />
      </svg>
    </>
  );
};

const Sendero: React.FC<{s: number}> = ({s}) => {
  const progreso = interpolate(s, [T_PRESENCIA, T_PRESENCIA + 3.5], [0, 1], {...clamp, easing: Easing.out(Easing.cubic)});
  return (
    <svg width={W} height={700} style={{position: 'absolute', left: 0, top: 1240}} viewBox={`0 0 ${W} 700`}>
      <linearGradient id="gPath" x1="0" y1="1" x2="0" y2="0"><stop offset="0%" stopColor="#d99f68" stopOpacity={0.85} /><stop offset="60%" stopColor="#f3ca93" stopOpacity={0.7} /><stop offset="100%" stopColor="#fff2cf" stopOpacity={0.9} /></linearGradient>
      <path d="M440 700 C 490 530, 560 410, 520 260 S 550 110, 540 30 L 565 30 C 580 110, 560 260, 600 410 S 640 540, 710 700 Z" fill="url(#gPath)" style={{clipPath: `inset(${(1 - progreso) * 100}% 0 0 0)`}} />
    </svg>
  );
};

const Carga: React.FC<{s: number}> = ({s}) => {
  const surge = interpolate(s, [T_DESPERTASTE, T_PESO + 0.6], [0, 1], clamp);
  const seEntrega = interpolate(s, [T_ENTREGO, T_ENTREGO + 3], [0, 1], {...clamp, easing: Easing.inOut(Easing.cubic)});
  const opac = Math.max(0, surge * (1 - seEntrega * 0.98));
  if (opac <= 0.005) return null;
  return (
    <div style={{position: 'absolute', left: W / 2 + 30, top: 1390 - seEntrega * 380, transform: `translate(-50%, -50%) scale(${1 - seEntrega * 0.95})`, opacity: opac}}>
      <svg width={220} height={180} viewBox="0 0 220 180">
        <radialGradient id="gRock" cx="40%" cy="35%" r="65%"><stop offset="0%" stopColor="#535166" /><stop offset="100%" stopColor="#171622" /></radialGradient>
        <path d="M30 110 C 20 70, 60 25, 110 20 C 160 15, 195 55, 200 95 C 205 140, 170 165, 115 170 C 60 175, 38 145, 30 110 Z" fill="url(#gRock)" />
      </svg>
    </div>
  );
};

const Munequito: React.FC<{s: number; postura: number}> = ({s, postura}) => (
  <div style={{position: 'absolute', left: 450, top: 1370 + Math.sin(s * 1.4) * 3.5, width: 180, height: 290}}>
    <div style={{position: 'absolute', left: 15, top: 260, width: 140, height: 26, borderRadius: '50%', background: 'rgba(12,10,24,0.4)', filter: 'blur(5px)'}} />
    <svg width={180} height={290} viewBox="0 0 180 290">
      <linearGradient id="gManto" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stopColor="#556082" /><stop offset="100%" stopColor="#1f2334" /></linearGradient>
      <path d={`M 40 ${130 + postura * 8} Q 85 ${100 + postura * 8} 130 ${130 + postura * 8} L 146 265 Q 85 275 24 265 Z`} fill="url(#gManto)" />
      <circle cx={85} cy={76 - postura * 7} r={34} fill="#f3be94" />
      <path d={`M 55 ${68 - postura * 7} Q 85 ${36 - postura * 7} 115 ${68 - postura * 7} Q 118 ${92 - postura * 7} 108 ${98 - postura * 7} Q 85 ${78 - postura * 7} 58 ${94 - postura * 7} Z`} fill="#31222b" />
    </svg>
  </div>
);

const Angel: React.FC<{s: number; aparicion: number; abrazo: number}> = ({s, aparicion, abrazo}) => {
  if (aparicion <= 0.01) return null;
  const aleteo = Math.sin(s * 1.8) * 12;
  return (
    <div style={{position: 'absolute', left: 360, top: 1140 + Math.sin(s * 1.1) * 8, width: 360, height: 480, opacity: aparicion, transform: `scale(${1 + abrazo * 0.1})`}}>
      <div style={{position: 'absolute', left: 135, top: 30, width: 90, height: 28, borderRadius: '50%', border: '4px solid #fff5cc', boxShadow: '0 0 25px 8px rgba(255,230,140,0.8)'}} />
      <svg width={360} height={480} viewBox="0 0 360 480">
        <linearGradient id="gAla" x1="1" y1="0.5" x2="0" y2="0"><stop offset="0%" stopColor="rgba(255,255,255,0.8)" /><stop offset="100%" stopColor="transparent" /></linearGradient>
        <path d={`M 160 170 C 90 ${90 + aleteo}, 20 ${130 - aleteo}, 10 ${250 + abrazo * 40} C 10 320, 90 280, 155 240 Z`} fill="url(#gAla)" />
        <path d={`M 200 170 C 270 ${90 - aleteo}, 340 ${130 + aleteo}, 350 ${250 + abrazo * 40} C 350 320, 270 280, 205 240 Z`} fill="url(#gAla)" transform="scale(-1,1) translate(-360,0)" />
        <circle cx={180} cy={85} r={32} fill="rgba(255,250,230,0.9)" />
        <path d="M 148 130 C 160 115, 200 115, 212 130 L 235 340 C 200 360, 160 360, 125 340 Z" fill="rgba(255,220,150,0.5)" />
      </svg>
    </div>
  );
};

const Particulas: React.FC<{s: number; dorada: number}> = ({s, dorada}) => (
  <AbsoluteFill>
    {Array.from({length: 30}).map((_, i) => {
      const x = ((i * 137) % W) + Math.sin(s * 0.5 + i) * 25;
      const y = H - (((i * 223) + s * (20 + (i % 5) * 10)) % (H + 100));
      return <div key={i} style={{position: 'absolute', left: x, top: y, width: 4, height: 4, borderRadius: 2, background: dorada > 0.5 ? '#ffe9b8' : '#d8e6ff', opacity: 0.3 + 0.4 * Math.sin(s + i)}} />;
    })}
  </AbsoluteFill>
);

export const Escena: React.FC = () => {
  const {s} = useS();
  const aurora = interpolate(s, [T_DESPERTASTE, T_GRACIAS + 2], [0, 1], clamp);
  const dorada = interpolate(s, [T_ENTREGO, T_CALMA + 3], [0, 1], clamp);
  const salidaSol = interpolate(s, [T_SERENIDAD, T_SOLEDAD + 2], [0, 1], clamp);
  const presenciaAngel = interpolate(s, [T_PRESENCIA, T_PRESENCIA + 2], [0, 1], clamp);
  const abrazo = interpolate(s, [T_CONMIGO, T_CONMIGO + 2], [0, 1], clamp);
  const postura = interpolate(s, [T_ENTREGO, T_SERENIDAD + 2], [0, 1], clamp);
  const zoom = 1.05 + 0.05 * (s / Math.max(DUR, 1));
  return (
    <AbsoluteFill style={{overflow: 'hidden', backgroundColor: '#0c0f24'}}>
      <AbsoluteFill style={{transform: `scale(${zoom}) translateX(${Math.sin(s * 0.2) * 15}px)`, transformOrigin: '50% 70%'}}>
        <Cielo aurora={aurora} dorada={dorada} />
        <SolNaciente salida={salidaSol} s={s} />
        <HacesLuz intensidad={interpolate(s, [T_FUERZAS, T_CAMBIAR + 3], [0.2, 1], clamp)} s={s} />
        <Colinas aurora={aurora} dorada={dorada} deriva={Math.sin(s * 0.2) * 15} />
        <Sendero s={s} />
        <Angel s={s} aparicion={presenciaAngel} abrazo={abrazo} />
        <Munequito s={s} postura={postura} />
        <Carga s={s} />
        <Particulas s={s} dorada={dorada} />
      </AbsoluteFill>
      <AbsoluteFill style={{background: 'radial-gradient(circle at 50% 50%, transparent 40%, rgba(0,0,0,0.3) 100%)'}} />
    </AbsoluteFill>
  );
};
